import{_ as t,o as d,c as a,a2 as r}from"./chunks/framework.BetZR81g.js";const l=JSON.parse('{"title":"API 导航","description":"","frontmatter":{"lang":"zh-CN","sourcePath":"docs/api.zh-CN.md"},"headers":[],"relativePath":"zh/guide/api.md","filePath":"zh/guide/api.md"}'),o={name:"zh/guide/api.md"};function i(c,e,h,n,s,p){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="api-导航" tabindex="-1">API 导航 <a class="header-anchor" href="#api-导航" aria-label="Permalink to &quot;API 导航&quot;">​</a></h1><blockquote><p>sfml.js 以 SFML 3.1.0 为基础。手写指南解释使用方式、返回值和 Node.js 适配；完整签名与类型约束由 <a href="/zh/reference/" target="_self">TypeDoc</a> 从源码生成。</p></blockquote><p><a href="/zh/guide/">文档首页</a> · <a href="/zh/guide/getting-started">快速开始</a> · <a href="/zh/guide/concepts">核心概念</a></p><p>所有公开接口均从 <code>sfml.js</code> 导入，导出清单见 <a href="https://github.com/XadillaX/node-sfml/blob/main/src/index.ts" target="_blank" rel="noreferrer">src/index.ts</a>。业务代码无需访问 <code>dist/internal</code> 或原生模块句柄。</p><h2 id="按任务选择" tabindex="-1">按任务选择 <a class="header-anchor" href="#按任务选择" aria-label="Permalink to &quot;按任务选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>文档</th><th>主要接口</th></tr></thead><tbody><tr><td>计算坐标、角度和帧时间</td><td><a href="/zh/guide/system">System</a></td><td>Vector2／3、Angle、Time、Clock、具名运算符</td></tr><tr><td>接入自定义文件来源</td><td><a href="/zh/guide/system#input-streams">输入流</a></td><td>InputStream、MemoryInputStream、FileInputStream</td></tr><tr><td>打开窗口、接收输入</td><td><a href="/zh/guide/window">Window</a></td><td>RenderWindow、Window、Event、Keyboard、Mouse</td></tr><tr><td>显示图片与动画</td><td><a href="/zh/guide/graphics">Graphics</a></td><td>Image、Texture、Sprite</td></tr><tr><td>绘制形状与文字</td><td><a href="/zh/guide/graphics">Graphics</a></td><td>Shape、Font、Glyph、Text</td></tr><tr><td>相机、离屏合成与批量几何</td><td><a href="/zh/guide/graphics">Graphics</a></td><td>View、RenderTexture、VertexArray、VertexBuffer</td></tr><tr><td>自定义绘制与着色器</td><td><a href="/zh/guide/graphics">Graphics</a></td><td>Drawable、RenderStates、Shader、Glsl</td></tr><tr><td>播放、录音及音频处理</td><td><a href="/zh/guide/audio">Audio</a></td><td>SoundBuffer、Sound、Music、SoundStream、SoundRecorder</td></tr><tr><td>联网与传输文件</td><td><a href="/zh/guide/network">Network</a></td><td>Packet、TcpSocket、UdpSocket、Http、Ftp、Sftp</td></tr></tbody></table><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p><code>Vector2</code>／<code>Vector3</code> 支持多种标量类型；<code>Vector2i/u/f</code> 和 <code>Vector3i/u/f</code> 是常用特化。<code>degrees()</code>／<code>radians()</code> 创建 Angle，时间工厂创建 Time。</p><p>JavaScript 没有 C++ 运算符重载，对应操作使用 <code>add()</code>、<code>multiply()</code>、<code>equal()</code> 及 <code>*Assign()</code>。<code>Clock</code>、异步 <code>sleep()</code>、<code>TimeoutWithPredicate</code>、输入流、<code>Unicode</code> 和错误日志接口也属于本模块。</p><p>详见 <a href="/zh/guide/system">System</a>。</p><h2 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window&quot;">​</a></h2><p><code>Window</code> 提供系统窗口及 OpenGL 上下文；二维绘制一般使用同时具有 Window 与 RenderTarget 能力的 <code>RenderWindow</code>。</p><p>事件可通过 <code>pollEvent()</code>、<code>handleEvents()</code> 或同步 <code>waitEvent()</code> 获取。键盘、鼠标、摇杆和传感器还提供实时查询。<code>Clipboard</code>、<code>Cursor</code>、<code>Context</code> 与 <code>Vulkan</code> 覆盖系统集成。</p><p>详见 <a href="/zh/guide/window">Window</a>。</p><h2 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h2><p>Image 保存 CPU 侧像素，Texture 保存 GPU 纹理，Sprite 引用纹理进行绘制。Shape 提供圆、矩形、凸多边形和自定义凸形状；Font 与 Text 提供字体加载、排版及可编辑顶点。</p><p>RenderTarget 统一窗口和离屏目标的绘制接口。View 控制相机与视口，RenderStates 控制变换、混合、模板、纹理和 Shader。顶点数组及 GPU 顶点缓冲用于直接组织几何。</p><p>详见 <a href="/zh/guide/graphics">Graphics</a> 和 <a href="/zh/guide/concepts#draw-snapshots">绘制快照</a>。</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><p>短音效使用 SoundBuffer + Sound，长音频使用 Music。SoundSource 提供音量、声像和空间音频属性；SoundStream、SoundRecorder、EffectProcessor 使用 Worker 回调处理自定义数据。</p><p>详见 <a href="/zh/guide/audio">Audio</a>，特别注意样本数、声道排列及缓冲有效期。</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Network 使用 Node.js 传输实现 SFML 风格 API，生产代码不调用 SFML C++ Network。Packet 保留 SFML 编码约定；TCP、UDP、DNS、TLS、HTTP、FTP 和 SFTP 的 I/O 使用 Promise。</p><p>详见 <a href="/zh/guide/network">Network</a>，包括状态返回、部分发送、协议限制与关闭方式。</p><h2 id="兼容边界" tabindex="-1">兼容边界 <a class="header-anchor" href="#兼容边界" aria-label="Permalink to &quot;兼容边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前行为</th></tr></thead><tbody><tr><td>C++ 指针、引用输出参数</td><td>用对象、视图或返回对象表达</td></tr><tr><td>C++ 模板及运算符</td><td>用明确的标量标签、类和具名函数表达</td></tr><tr><td>文件加载</td><td>使用 Promise，具体失败状态按接口保留</td></tr><tr><td>析构</td><td>Native 所有权配合 JS 引用；有关闭接口的资源应显式关闭</td></tr><tr><td><code>drawAsync()</code>／<code>displayAsync()</code></td><td>未提供，旧示例明确报告不支持</td></tr><tr><td>Android SuspendAwareClock</td><td>有条件编译接口；当前下载流程面向桌面</td></tr><tr><td>Vulkan</td><td>已导出查询接口；可用性取决于 SFML 平台后端，macOS 后端不可用</td></tr></tbody></table><p>平台构建与测试范围见 <a href="/zh/guide/development#testing">开发指南</a>。</p><p><a id="sfml-cpp-reference"></a></p><h2 id="sfml-c-参考" tabindex="-1">SFML C++ 参考 <a class="header-anchor" href="#sfml-c-参考" aria-label="Permalink to &quot;SFML C++ 参考&quot;">​</a></h2><p><a href="https://www.sfml-dev.org/documentation/3.1.0/" target="_blank" rel="noreferrer">SFML 3.1.0 官方文档</a> 解释 C++ 类和上游概念，TypeDoc 则是 sfml.js 的 JavaScript／TypeScript 签名参考。两者配合阅读：先用上游文档理解功能，再按本项目指南调用。</p><p>各模块的上游链接与适配边界：<a href="/zh/guide/system#sfml-cpp-reference">System</a>、<a href="/zh/guide/window#sfml-cpp-reference">Window</a>、<a href="/zh/guide/graphics#sfml-cpp-reference">Graphics</a>、<a href="/zh/guide/audio#sfml-cpp-reference">Audio</a>、<a href="/zh/guide/network#sfml-cpp-reference">Network</a>。</p>',31)])])}const f=t(o,[["render",i]]);export{l as __pageData,f as default};
